llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Theophylline, the closest xanthine analogue, has essentially 100% absolute oral bioavailability with no first-pass effect; the query is a theophylline derivative, strongly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paraxanthine, another dimethylxanthine, is rapidly and completely absorbed with high bioavailability in healthy volunteers, supporting high F for the xanthine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Temozolomide, a small N-methyl heterocycle, has approximately 100% oral bioavailability, supporting high F for this class of polar heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Emtricitabine, a polar nucleoside with an oxathiolane ring, has 93% absolute oral bioavailability, showing that cyclic ether/thioether nucleoside-like scaffolds can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Lamivudine has 86% absolute oral bioavailability in humans, further supporting high F for polar nucleoside analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Zalcitabine has about 80% oral bioavailability in adults, supporting high F for this nucleoside analogue family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ondansetron has 66% absolute oral bioavailability, well above the 20% threshold, supporting high F for a related fused heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Cladribine has about 40% absolute oral bioavailability despite incomplete absorption and BCRP efflux, still well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Didanosine fed-state F was 0.17, below 20%, but this reflects acid lability and food effects of a deoxynucleoside, not the neutral xanthine query; it is the only sub-threshold evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is doxofylline, a theophylline derivative. The closest analogue theophylline has essentially complete oral bioavailability, and multiple xanthines, heterocycles, and polar nucleoside analogues show F well above 20%. The only sub-threshold evidence (didanosine) is acid-labile and food-sensitive, not representative of the neutral xanthine scaffold. Therefore F ≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for doxofylline itself is present in the supplied evidence.",
    "The metabolic fate and acid stability of the dioxolane moiety in doxofylline are not directly quantified.",
    "The only sub-20% evidence (didanosine) is condition-dependent and mechanistically distinct, limiting its weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

